<?php
declare(strict_types=1);
require_once __DIR__.'/auth.php';cpmsPropertyRequire('reports.manage');require_once dirname(__DIR__).'/includes/asset_service.php';
$categories=['Structure','Mechanical & Electrical','Fire Safety','Security','Housekeeping','Landscape','Common Facilities'];$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){$scores=[];foreach($categories as $i=>$cat){$v=(float)($_POST['score'][$i]??-1);if($v<0||$v>100)$errors[]='All scores must be between 0 and 100.';$scores[$cat]=$v;}if(!$errors){$overall=array_sum($scores)/count($scores);$rating=cpmsBciRating($overall);$date=(string)($_POST['assessment_date']??date('Y-m-d'));$title=trim((string)($_POST['assessment_title']??'Building Condition Assessment'));$remarks=trim((string)($_POST['remarks']??''));$uid=(int)$propertyPortalUser['id'];$uname=(string)$propertyPortalUser['full_name'];$conn->begin_transaction();try{$s=$conn->prepare('INSERT INTO bci_assessments(property_id,assessment_date,assessment_title,overall_score,overall_rating,remarks,assessed_by_id,assessed_by_name) VALUES(?,?,?,?,?,NULLIF(?,""),?,?)');if(!$s)throw new RuntimeException('Unable to prepare BCI assessment.');$s->bind_param('issdssis',$currentPropertyId,$date,$title,$overall,$rating,$remarks,$uid,$uname);if(!$s->execute())throw new RuntimeException($s->error);$aid=(int)$s->insert_id;$s->close();$s=$conn->prepare('INSERT INTO bci_scores(assessment_id,property_id,category_name,score,notes) VALUES(?,?,?,?,NULL)');if(!$s)throw new RuntimeException('Unable to prepare category scores.');foreach($scores as $cat=>$score){$s->bind_param('iisd',$aid,$currentPropertyId,$cat,$score);if(!$s->execute())throw new RuntimeException($s->error);}$s->close();$conn->commit();header('Location: bci.php');exit;}catch(Throwable $e){$conn->rollback();$errors[]=$e->getMessage();}}}
$pageTitle='New BCI Assessment';$activeMenu='bci';require __DIR__.'/includes/layout_header.php';require __DIR__.'/includes/layout_sidebar.php';require __DIR__.'/includes/layout_topbar.php';?>
<link rel="stylesheet" href="assets/asset-register.css"><section class="page-heading"><div><span class="section-label">BUILDING PERFORMANCE</span><h1>New BCI Assessment</h1><p>Score each category from 0 to 100.</p></div></section><?php foreach($errors as $e):?><div class="alert-error"><?php echo propertyPortalEscape($e);?></div><?php endforeach;?><form method="post" class="panel asset-form"><div class="form-grid"><div class="field-group"><label>Assessment Date</label><input type="date" name="assessment_date" value="<?php echo date('Y-m-d');?>" required></div><div class="field-group"><label>Assessment Title</label><input name="assessment_title" value="Building Condition Assessment" required></div><?php foreach($categories as $i=>$cat):?><div class="field-group"><label><?php echo propertyPortalEscape($cat);?> (%)</label><input type="number" min="0" max="100" step="0.1" name="score[<?php echo $i;?>]" required></div><?php endforeach;?></div><div class="field-group"><label>Remarks</label><textarea name="remarks" rows="4"></textarea></div><button class="button button-primary">Save Assessment</button><a class="button button-secondary" href="bci.php">Cancel</a></form><?php require __DIR__.'/includes/layout_footer.php';?>
